/* ambient palin: four players actually play, the ball passed, dribbled and stolen inside the field */
function palAmbient(sc){
  const X=sc.x*T+6,Y=sc.y*T+14,W=sc.w*T-12,H=sc.h*T-16;
  if(!sc.am){sc.am={bx:X+W/2,by:Y+H/2,vx:0,vy:0,hold:-1,t:0,cool:0};sc.pl.forEach((p,i)=>{p.vx=0;p.vy=0})}
  const a=sc.am,team=i=>i<2?0:1,goalX=i=>team(i)===0?X+W:X;
  a.t++;if(a.cool>0)a.cool--;
  // ball
  if(a.hold>=0){const h=sc.pl[a.hold],d=team(a.hold)===0?1:-1;a.bx+=(h.x+d*9-a.bx)*.5;a.by+=(h.y+6-a.by)*.5;
    const toGoal=Math.abs(goalX(a.hold)-h.x),mates=[0,1,2,3].filter(j=>j!==a.hold&&team(j)===team(a.hold)),m=sc.pl[mates[0]],ahead=(m.x-h.x)*d>24;
    if(toGoal<34||(a.t>a.kick&&ahead)){
      let tx,ty;if(toGoal>=34){tx=m.x+d*14;ty=m.y+4}else{tx=goalX(a.hold)+d*8;ty=Y+H*(.3+Math.random()*.4)}
      const dx=tx-a.bx,dy=ty-a.by,dd=Math.hypot(dx,dy)||1,sp=2.2+Math.random()*.8;a.vx=dx/dd*sp;a.vy=dy/dd*sp;a.hold=-1;a.cool=14}}
  else{a.bx+=a.vx;a.by+=a.vy;a.vx*=.955;a.vy*=.955;
    if(a.bx<X||a.bx>X+W){   // over the end line: a point, and play restarts from the middle toward the other end
      a.bx=X+W/2;a.by=Y+H/2;a.vx=0;a.vy=0;a.cool=30;a.goals=(a.goals||0)+1}
    if(a.by<Y||a.by>Y+H){a.vy*=-.7;a.by=Math.max(Y,Math.min(Y+H,a.by))}}
  // players: with the ball, the holder dribbles and the mate runs ahead; without it, one presses and one covers the goal
  const ht=a.hold>=0?team(a.hold):-1;
  const near=[0,1].map(tm=>{let b=-1,bd=1e9;sc.pl.forEach((p,i)=>{if(team(i)!==tm)return;const d=Math.hypot(p.x-a.bx,p.y-a.by);if(d<bd){bd=d;b=i}});return b});
  sc.pl.forEach((p,i)=>{const tm=team(i),d=tm===0?1:-1,lane=i%2?Y+H*.8:Y+H*.15;let tx,ty,sp;
    if(a.hold===i){tx=goalX(i);ty=p.y+Math.sin(a.t/13+i)*5;sp=.8}
    else if(ht===tm){tx=a.bx+d*40;ty=lane;sp=.85}
    else if(near[tm]===i){const h=a.hold>=0?sc.pl[a.hold]:{x:a.bx,y:a.by};tx=h.x-d*10;ty=h.y;sp=.62}
    else{tx=a.bx-d*36;ty=lane;sp=.6}
    tx=Math.max(X+6,Math.min(X+W-6,tx));
    const dx=tx-p.x,dy=ty-p.y,dd=Math.hypot(dx,dy);
    if(dd>2){const s=Math.min(sp,dd);p.x+=dx/dd*s;p.y+=dy/dd*s;p.mv=true;p.dir=Math.abs(dx)>=Math.abs(dy)*.8?(dx>0?'right':'left'):(dy>0?'down':'up')}
    else{p.mv=false;p.dir=a.bx>p.x?'right':'left'}
    p.x=Math.max(X+4,Math.min(X+W-4,p.x));p.y=Math.max(Y,Math.min(Y+H-2,p.y));
    // pick up a slow ball, or steal it from an opponent who gets too close
    if(a.hold<0&&!a.cool&&Math.hypot(p.x-a.bx,p.y+6-a.by)<8&&Math.hypot(a.vx,a.vy)<1.6){a.hold=i;a.t=0;a.kick=40+Math.random()*80}
    else if(a.hold>=0&&team(a.hold)!==tm&&!a.cool&&Math.hypot(p.x-sc.pl[a.hold].x,p.y-sc.pl[a.hold].y)<9&&Math.random()<.006){a.hold=i;a.t=0;a.kick=40+Math.random()*80;a.cool=40}});
  sc.bx=a.bx;sc.by=a.by;
}

/* the lof comes alive: NPCs who stood still now stroll a short loop around their spot, pause, and look at you as you pass */
function npcAmbient(){
  const STAY=new Set(['rewe','ngen','ngen2','ngen3','ngen4','ngen5','yewen','llawfen','chumpall','chumpallm']);
  for(const e of ents){
    if(e.kind!=='npc'||e.path||e.seated||e.act||STAY.has(e.look)||M.indoor)continue;
    const R=['teacher','machi','seller','cook','lonko','lonko2','lonko3','lonko4','lonko5'].includes(e.look)?2:3;
    const hx=e.x,hy=e.y,ok=(x,y)=>walk(x,y)&&grid[y][x]!=='S';
    // a straight leg, x first then y, so the route never cuts through a ruka or a tree
    const legOK=(a,b)=>{let [x,y]=a;while(x!==b[0]){x+=Math.sign(b[0]-x);if(!ok(x,y))return false}while(y!==b[1]){y+=Math.sign(b[1]-y);if(!ok(x,y))return false}return true};
    const pts=[[hx,hy]];
    for(let k=0;k<40&&pts.length<4;k++){const c=[hx+rnd(2*R+1)-R,hy+rnd(2*R+1)-R];if((c[0]!==hx||c[1]!==hy)&&ok(...c)&&legOK(pts[pts.length-1],c))pts.push(c)}
    if(pts.length<2||!legOK(pts[pts.length-1],pts[0]))continue;
    e.path=pts;e.pi=1;e.pause=40+rnd(90);e.spd=18+rnd(10);e.cd=rnd(60);e.wait=rnd(120);e.amb=1}
}
/* while paused, a strolling NPC turns to face you when you come near */
function npcFace(){for(const e of ents)if(e.amb&&e.wait>0&&Math.abs(e.x-P.x)+Math.abs(e.y-P.y)<=3)e.dir=Math.abs(P.x-e.x)>Math.abs(P.y-e.y)?(P.x>e.x?'right':'left'):(P.y>e.y?'down':'up')}

/* ================= NEW GRAPHICS (BETA) =================
   Gemini-drawn heroes, people and wekufü, chosen in Settings (Gráficos: clásicos / nuevos). Off by default; the
   classic sprites stay untouched underneath, so switching back is instant. With the new graphics the lof also comes
   alive: villagers stroll around their spots and the palin players run the length of the cancha. */
const GEM_KEY='kewun_gfx_beta';let GEM_ON=false,GEM_READY=false;const GEMI={pc:{},npc:{},seat:{},en:{}};
try{GEM_ON=localStorage.getItem(GEM_KEY)==='1'}catch(e){}
function gemLoad(){if(GEM_READY||gemLoad.busy)return;gemLoad.busy=1;let n=0,done=0;
  const ld=(u,set)=>{n++;const i=new Image();i.onload=()=>{set(i);if(++done===n){GEM_READY=true;gemFlush()}};i.src=u};
  for(const g of ['pc','npc'])for(const k in GEMD[g]){GEMI[g][k]={};for(const d in GEMD[g][k]){const a=GEMD[g][k][d];GEMI[g][k][d]=[];a.forEach((u,j)=>ld(u,i=>GEMI[g][k][d][j]=i))}}
  for(const k in GEMD.seat){GEMI.seat[k]={};for(const d in GEMD.seat[k])ld(GEMD.seat[k][d],i=>GEMI.seat[k][d]=i)}
  for(const k in GEMD.en)ld(GEMD.en[k],i=>GEMI.en[k]=i)}
function gemFlush(){for(const k in CCACHE)delete CCACHE[k];for(const k in ECACHE)delete ECACHE[k]}
function gemSet(on){GEM_ON=!!on;try{localStorage.setItem(GEM_KEY,on?'1':'0')}catch(e){}gemFlush();
  if(on){gemLoad();if(typeof ents!=='undefined'&&typeof M!=='undefined'&&M)npcAmbient()}
  else if(typeof ents!=='undefined')for(const e of ents)if(e.amb){delete e.path;e.amb=0;e.mv=false}}
function gemCv(im,flip,w,h){const W=Math.max(w,im.width),[c,x]=mk(W,Math.max(h,im.height));x.imageSmoothingEnabled=false;
  if(flip){x.translate(W,0);x.scale(-1,1)}x.drawImage(im,Math.round((W-im.width)/2),c.height-im.height);return c}
const _gCS=ctCharSprite,_gCB=ctCharSpriteBig,_gEC=enemyCanvas,_gUM=updateMap,_gLM=loadMap;
ctCharSprite=function(look,dir,fr,seated,tn,ey,hr){
  if(!(GEM_ON&&GEM_READY))return _gCS.apply(this,arguments);
  const d=dir==='right'?'left':(dir||'down'),flip=dir==='right';
  if(seated){const q=GEMI.seat[look];return q&&q[d]?gemCv(q[d],flip,18,24):_gCS.apply(this,arguments)}
  const g=GEMI.pc[look]||GEMI.npc[look];if(!g||!g[d])return _gCS.apply(this,arguments);
  const key='GEM'+look+dir+(fr|0)%4;if(CCACHE[key])return CCACHE[key];
  return CCACHE[key]=gemCv(g[d][(((fr|0)%4)+4)%4],flip,18,32)};
ctCharSpriteBig=function(look,dir,fr){
  if(!(GEM_ON&&GEM_READY)||!GEMI.pc[look])return _gCB.apply(this,arguments);
  const k=(typeof B!=='undefined'&&B&&B.red>0)?3:fr>0?(fr>=2?1:2):0,key='GEMB'+look+dir+k;if(CCACHE[key])return CCACHE[key];
  return CCACHE[key]=gemCv(GEMI.pc[look].battle[k],dir!=='left',48,74)};
enemyCanvas=function(t,size,fr){const im=GEM_ON&&GEM_READY&&GEMI.en[t];if(!im)return _gEC.apply(this,arguments);
  const key='GEM'+t+size+'_'+fr;if(ECACHE[key])return ECACHE[key];const bs=(ET[t]&&ET[t].bs)||44,s=GEMD.sz[t]||{cw:im.width+6,ch:im.height+6};
  const sc=size<bs*.7?size/bs:1,cw=Math.round(s.cw*sc),ch=Math.round(s.ch*sc),[cv,c]=mk(cw,ch);c.imageSmoothingEnabled=false;
  const w=Math.round(im.width*sc),h=Math.round(im.height*sc);c.drawImage(im,Math.round((cw-w)/2),ch-h-(fr?1:0)-Math.round(3*sc),w,h);return ECACHE[key]=cv};
updateMap=function(){_gUM.apply(this,arguments);if(!GEM_ON||!GEM_READY||typeof active!=='undefined'&&active)return;
  if(!(typeof PAL!=='undefined'&&PAL&&PAL.on))for(const sc of SCN)if(sc.type==='palin')palAmbient(sc);npcFace()};
loadMap=function(){const r=_gLM.apply(this,arguments);if(GEM_ON)npcAmbient();return r};
if(GEM_ON)gemLoad();
